import { useEffect, useState } from "react";
import axios from "axios";

export default function Editar() {
  const [user, setUser] = useState(null);
  const [form, setForm] = useState({});

  useEffect(() => {
    axios.get("http://localhost:3001/usuario").then(res => {
      setUser(res.data);
      setForm(res.data);
    });
  }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    const reader = new FileReader();
    if (form.imagem instanceof File) {
      reader.onload = () => {
        axios.put(`http://localhost:3001/usuario/${user.id}`, {
          ...form,
          imagem: reader.result
        }).then(() => alert("Atualizado com sucesso!"))
          .catch(() => alert("Erro ao atualizar"));
      };
      reader.readAsDataURL(form.imagem);
    } else {
      axios.put(`http://localhost:3001/usuario/${user.id}`, form)
        .then(() => alert("Atualizado com sucesso!"))
        .catch(() => alert("Erro ao atualizar"));
    }
  };

  if (!user) return <p>Carregando...</p>;

  return (
    <form onSubmit={handleSubmit}>
      {["nome", "idade", "rua", "bairro", "estado"].map(campo => (
        <div className="mb-3" key={campo}>
          <input
            type={campo === "idade" ? "number" : "text"}
            className="form-control"
            placeholder={campo}
            value={form[campo] || ""}
            onChange={e => setForm({ ...form, [campo]: e.target.value })}
          />
        </div>
      ))}
      <div className="mb-3">
        <textarea
          className="form-control"
          placeholder="Biografia"
          value={form.biografia || ""}
          onChange={e => setForm({ ...form, biografia: e.target.value })}
        ></textarea>
      </div>
      <div className="mb-3">
        <input type="file" className="form-control" onChange={e => setForm({ ...form, imagem: e.target.files[0] })} />
      </div>
      <button className="btn btn-warning">Salvar Alterações</button>
    </form>
  );
}
